// Get the incoming sensor value
let value = Number(msg.payload);

// Retrieve thresholds
let lowThreshold = Number(flow.get("lowThreshold", "file"));
let highThreshold = Number(flow.get("highThreshold", "file"));

// Retrieve override mode from dashboard input
// 0 = Auto, 1 = Force OFF, 2 = Force ON
let overrideMode = flow.get("overrideMode", "file") || 0;

node.status({ fill: "blue", shape: "dot", text: `H:${value} L:${lowThreshold} H:${highThreshold} Mode:${overrideMode}` });

// Output object
let outMsg = {};

// Handle override modes
if (overrideMode === 1) {
    outMsg.payload = 0;   // Force OFF
    return outMsg;
}
if (overrideMode === 2) {
    outMsg.payload = 1;   // Force ON
    return outMsg;
}


// --- Validate thresholds before proceeding ---
// If either threshold is missing/invalid, turn OFF and exit
if (isNaN(lowThreshold) || isNaN(highThreshold)) {
    outMsg.payload = 0;   // OFF
    return outMsg;
}

// --- Auto mode: threshold logic ---
if (lowThreshold >= highThreshold) {
    outMsg.payload = 0;   // OFF - invalid threshold range
} else if (value < lowThreshold) {
    outMsg.payload = 1;   // ON
} else if (value > highThreshold) {
    outMsg.payload = 0;   // OFF
} else {
    return null; // Between thresholds → do nothing
}

return outMsg;

const low  = flow.get('lowThreshold',  'file');
const high = flow.get('highThreshold', 'file');

if (low  === undefined || low  === null) { node.warn('lowThreshold not set');  }
if (high === undefined || high === null) { node.warn('highThreshold not set'); }

return [
    { payload: low  },
    { payload: high }
];

//flow.set('hum_table', null); // clears table - turn back off

var sensors = flow.get('hum_table') || {
    'Moapa': { loc: 'Outdoor (Moapa)', values: [], cur: '--', min: '--', max: '--', avg: '--' },
    'F.F. ezo1 %': { loc: 'Fruiting Front - ezo1', values: [], cur: '--', min: '--', max: '--', avg: '--' },
    'F.F. scd1 %': { loc: 'Fruiting Front - scd1', values: [], cur: '--', min: '--', max: '--', avg: '--' },
    'F.R. ezo2 %': { loc: 'Fruiting Rear - ezo2', values: [], cur: '--', min: '--', max: '--', avg: '--' },
    'F.R. scd2 %': { loc: 'Fruiting Rear - scd2', values: [], cur: '--', min: '--', max: '--', avg: '--' },
    'Incub. ezo3 %': { loc: 'Incubation - ezo3', values: [], cur: '--', min: '--', max: '--', avg: '--' },
    'Incub. scd3 %': { loc: 'Incubation - scd3', values: [], cur: '--', min: '--', max: '--', avg: '--' },
    'Pre-Con %': { loc: 'Pre-Con Govee', values: [], cur: '--', min: '--', max: '--', avg: '--' },
    'Lab %': { loc: 'Lab Govee', values: [], cur: '--', min: '--', max: '--', avg: '--' }

};

var key = msg.topic;

if (sensors[key] !== undefined) {
    var val = parseFloat(msg.payload);
    if (!isNaN(val)) {
        var now = Date.now();
        var cutoff = now - 1440 * 60 * 1000;

        if (!sensors[key].values) sensors[key].values = [];
        sensors[key].values.push({ t: now, v: val });
        sensors[key].values = sensors[key].values.filter(function (e) { return e.t >= cutoff; });

        var vals = sensors[key].values.map(function (e) { return e.v; });
        var mn = Math.min.apply(null, vals);
        var mx = Math.max.apply(null, vals);
        var av = vals.reduce(function (a, b) { return a + b; }, 0) / vals.length;

        sensors[key].cur = val.toFixed(1) + ' %';
        sensors[key].min = mn.toFixed(1) ;
        sensors[key].max = mx.toFixed(1) ;
        sensors[key].avg = (Math.round(av * 100) / 100).toFixed(1);
    }
}

flow.set('hum_table', sensors);
msg.payload = Object.values(sensors);
return msg;

